 const [recordings,setRecordings]=useState<SavedRecording[]>([]),[recording,setRecording]=useState(false),[audioLevels,setAudioLevels]=useState<number[]>(Array(36).fill(8)),[recordPaused,setRecordPaused]=useState(false),[activeBlob,setActiveBlob]=useState<Blob|null>(null),[activeMime,setActiveMime]=useState(''),[activeUrl,setActiveUrl]=useState(''),[showReview,setShowReview]=useState(false),[recordTitle,setRecordTitle]=useState(''),[recordSubject,setRecordSubject]=useState(''),[recordSeconds,setRecordSeconds]=useState(0),[notes,setNotes]=useState(''),[weakness,setWeakness]=useState(''),[target,setTarget]=useState(''),[score,setScore]=useState<Record<string,number>>({}),[editing,setEditing]=useState(''),[editValue,setEditValue]=useState(''),[toast,setToast]=useState('')
 const [debateTopic,setDebateTopic]=useState('Schools should replace most exams with project-based assessment.'),[debateSide,setDebateSide]=useState('Proposition'),[debateNotes,setDebateNotes]=useState('')
 const timerEnd=useRef(0),tick=useRef(0),recRef=useRef<MediaRecorder|null>(null),chunks=useRef<Blob[]>([]),stream=useRef<MediaStream|null>(null),recStart=useRef(0),recAccum=useRef(0),recInt=useRef<number|undefined>(undefined),audioCtxRef=useRef<AudioContext|null>(null),analyserRef=useRef<AnalyserNode|null>(null),rafRef=useRef<number>(0)
 const allTopics=useMemo(()=>[...seedTopics,...exerciseSeed,...customTopics,...topicBank.map(t=>{const assignedMode:Mode=t.mode==='prepared'?'Deep research':commonTopicCategories.has(t.category)?'Off the cuff':'Extended';return {id:t.id,title:t.title,category:t.category,mode:assignedMode,exercises:(assignedMode==='Off the cuff'?['qa','concise','conversation','questions','scenarios']:assignedMode==='Extended'?['explain','qa','story','movie','debate-both']:['explain','presentation','summary','rhetoric']) as ExerciseId[],level:(t.level==='Basic'?'Beginner':t.level==='Medium'?'Intermediate':'Advanced') as Topic['level'],research:assignedMode==='Deep research',source:'built-in' as const}})],[customTopics])
 useEffect(()=>{getRecordings().then(setRecordings).catch(()=>setToast('Recording storage is unavailable in this browser.'))},[])
