 useEffect(()=>{localStorage.setItem('cadence-theme',theme)},[theme]);useEffect(()=>{localStorage.setItem('cadence-color-pack',JSON.stringify(colorPack))},[colorPack]);useEffect(()=>{localStorage.setItem('cadence-phase-durations',JSON.stringify(phaseDurations))},[phaseDurations]);useEffect(()=>{localStorage.setItem('cadence-custom-topics',JSON.stringify(customTopics))},[customTopics]);useEffect(()=>{localStorage.setItem('cadence-recent',JSON.stringify(recent))},[recent]);useEffect(()=>{localStorage.setItem('cadence-questions',JSON.stringify(customQuestions))},[customQuestions])
 useEffect(()=>{if(!running||paused)return;tick.current=Date.now();const id=window.setInterval(()=>{const now=Date.now(),delta=Math.floor((now-tick.current)/1000);if(delta>0){tick.current+=delta*1000;setLifetime(v=>{const n=v+delta;localStorage.setItem('cadence-lifetime',String(n));return n})}const left=Math.max(0,Math.ceil((timerEnd.current-now)/1000));setRemaining(left);if(left===0){setRunning(false);setPaused(false);if(sound){try{const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);g.gain.value=.06;o.start();o.stop(c.currentTime+.25);o.onended=()=>c.close()}catch{}}setToast('Time is up. Review what you said.')}},200);return()=>clearInterval(id)},[running,paused,sound])
 useEffect(()=>()=>{clearInterval(recInt.current);stream.current?.getTracks().forEach(t=>t.stop());if(activeUrl)URL.revokeObjectURL(activeUrl)},[activeUrl])
